<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';zorunlu_rol('admin');$ligId=(int)($_GET['lig_id']??$_POST['lig_id']??0);$st=$pdo->prepare("SELECT * FROM ligler WHERE id=? AND tur='bireysel'");$st->execute([$ligId]);$lig=$st->fetch();if(!$lig){flash_set('hata','Bireysel lig bulunamadı.');redirect(BASE_URL.'/admin/ligler.php');}$gs=$pdo->prepare('SELECT id,grup_adi FROM gruplar WHERE lig_id=? ORDER BY grup_adi');$gs->execute([$ligId]);$gruplar=$gs->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['csrf']??'')){flash_set('hata','Güvenlik doğrulaması başarısız.');}elseif(($_POST['islem']??'')==='ekle'){$gid=(int)$_POST['grup_id'];$tarih=$_POST['tarih']??'';$saat=$_POST['saat']??null;$yer=trim($_POST['yer']??'');if(!$gid||!$tarih||$yer===''){flash_set('hata','Grup, tarih ve yer zorunludur.');}else{$pdo->prepare('INSERT INTO bireysel_fikstur(lig_id,grup_id,tarih,saat,yer,aciklama) VALUES(?,?,?,?,?,?)')->execute([$ligId,$gid,$tarih,$saat?:null,$yer,trim($_POST['aciklama']??'')?:null]);flash_set('basari','Bireysel lig fikstürü eklendi.');}}redirect(BASE_URL.'/admin/bireysel-fikstur.php?lig_id='.$ligId);}
if(($_GET['islem']??'')==='sil'&&($fid=(int)($_GET['id']??0))>0){$pdo->prepare('DELETE FROM bireysel_fikstur WHERE id=? AND lig_id=?')->execute([$fid,$ligId]);flash_set('basari','Fikstür kaydı silindi.');redirect(BASE_URL.'/admin/bireysel-fikstur.php?lig_id='.$ligId);}$fs=$pdo->prepare('SELECT f.*,g.grup_adi FROM bireysel_fikstur f JOIN gruplar g ON g.id=f.grup_id WHERE f.lig_id=? ORDER BY f.tarih,f.saat');$fs->execute([$ligId]);$liste=$fs->fetchAll();ob_start();?>
<div class="toolbar"><a class="btn" href="<?= BASE_URL ?>/admin/ligler.php">← Liglere dön</a></div><div class="card"><div class="card-head"><h2><?= e($lig['lig_adi']) ?> — bireysel fikstür</h2></div><p class="muted">Takım eşleşmesi yoktur; grubun sporcularının atış günü, saati ve yeri belirtilir.</p><form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="lig_id" value="<?= $ligId ?>"><input type="hidden" name="islem" value="ekle"><div class="grid-2"><label>Grup *<select name="grup_id" required><?php foreach($gruplar as $g):?><option value="<?= (int)$g['id'] ?>"><?= e($g['grup_adi']) ?></option><?php endforeach;?></select></label><label>Tarih *<input type="date" name="tarih" required></label></div><div class="grid-2"><label>Saat<input type="time" name="saat"></label><label>Atış yeri *<input name="yer" required placeholder="Atış poligonu / tesis"></label></div><label>Açıklama<input name="aciklama" placeholder="Örn. 1. ayak, kayıt saati 09:00"></label><div class="form-actions"><button class="btn btn-primary">Fikstüre ekle</button></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Grup</th><th>Tarih</th><th>Saat</th><th>Yer</th><th>Açıklama</th><th></th></tr></thead><tbody><?php foreach($liste as $f):?><tr><td><?= e($f['grup_adi']) ?></td><td><?= tr_tarih($f['tarih']) ?></td><td><?= tr_saat($f['saat']) ?></td><td><?= e($f['yer']) ?></td><td><?= e($f['aciklama']?:'—') ?></td><td><a class="btn btn-sm btn-danger" href="?lig_id=<?= $ligId ?>&islem=sil&id=<?= (int)$f['id'] ?>" onclick="return confirm('Fikstür kaydı silinsin mi?')">Sil</a></td></tr><?php endforeach;?></tbody></table></div>
<?php $admin_baslik='Bireysel Lig Fikstürü';$admin_aktif='ligler';$admin_icerik=ob_get_clean();require __DIR__.'/partials/layout.php'; ?>
